CREATE view  PGET_HED_REP as SELECT     dbo.PGET_HED.DATE AS DT, dbo.PGET_HED.MOLAH, dbo.PGET_HED.N_S, dbo.PGET_LST.DATE, dbo.TCOD_DPS.NAMES, dbo.PGET_LST.NO_AM, dbo.PGET_LST.NAHVA, dbo.PGET_LST.FHES_K, dbo.PGET_LST.FHES_M, dbo.PGET_LST.FHES_T, dbo.PGET_LST.THES_K, dbo.PGET_LST.THES_M, dbo.PGET_LST.THES_T, dbo.PGET_LST.SHARH, dbo.PGET_LST.MABL, dbo.PGET_LST.N_SERI, dbo.PGET_LST.BANK, '' AS kk, dbo.PGET_LST.ID, dbo.TCOD_DPSKIND.NAMES AS nonames, dbo.TOTA_HES.NAME AS FKNAME, dbo.DETA_HES.NAME AS FMNAME, dbo.TDETA_HES.NAME AS FTNAME, TOTA_HES_1.NAME AS TKNAME, DETA_HES_1.NAME AS TMNAME, TDETA_HES_1.NAME AS TTNAME, dbo.DEED_HED.base, dbo.SALA_DTL.EMZA AS emza1, SALA_DTL_1.EMZA AS emza2, SALA_DTL_2.EMZA AS emza3, dbo.PGET_HED.sgn1usid, dbo.PGET_HED.sgn2usid, dbo.PGET_HED.sgn3usid FROM         dbo.SALA_DTL SALA_DTL_1 RIGHT OUTER JOIN dbo.SALA_DTL RIGHT OUTER JOIN dbo.TDETA_HES TDETA_HES_1 INNER JOIN dbo.DETA_HES DETA_HES_1 ON TDETA_HES_1.N_KOL = DETA_HES_1.N_KOL AND TDETA_HES_1.NUMBER = DETA_HES_1.NUMBER INNER JOIN dbo.PGET_LST INNER JOIN dbo.TCOD_DPS ON dbo.PGET_LST.NO_AM = dbo.TCOD_DPS.CODE INNER JOIN dbo.TCOD_DPSKIND ON dbo.PGET_LST.NAHVA = dbo.TCOD_DPSKIND.CODE INNER JOIN dbo.PGET_HED ON dbo.PGET_LST.ID = dbo.PGET_HED.ID INNER JOIN dbo.TDETA_HES ON dbo.PGET_LST.FHES_K = dbo.TDETA_HES.N_KOL AND dbo.PGET_LST.FHES_M = dbo.TDETA_HES.NUMBER AND dbo.PGET_LST.FHES_T = dbo.TDETA_HES.TNUMBER INNER JOIN dbo.DETA_HES ON dbo.TDETA_HES.N_KOL = dbo.DETA_HES.N_KOL AND dbo.TDETA_HES.NUMBER = dbo.DETA_HES.NUMBER INNER JOIN dbo.TOTA_HES ON dbo.DETA_HES.N_KOL = dbo.TOTA_HES.NUMBER ON TDETA_HES_1.N_KOL = dbo.PGET_LST.THES_K AND  TDETA_HES_1.NUMBER = dbo.PGET_LST.THES_M AND TDETA_HES_1.TNUMBER = dbo.PGET_LST.THES_T INNER JOIN dbo.TOTA_HES TOTA_HES_1 ON DETA_HES_1.N_KOL = TOTA_HES_1.NUMBER INNER JOIN dbo.DEED_HED ON dbo.PGET_HED.N_S = dbo.DEED_HED.N_S LEFT OUTER JOIN dbo.SALA_DTL SALA_DTL_2 ON dbo.PGET_HED.sgn3usid = SALA_DTL_2.IDD ON dbo.SALA_DTL.IDD = dbo.PGET_HED.sgn1usid ON SALA_DTL_1.idd = dbo.PGET_HED.sgn2usid 
